insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('resumes','resumes',false,5242880,array['application/pdf']) on conflict (id) do update set public=false,file_size_limit=5242880,allowed_mime_types=array['application/pdf'];
create policy resumes_objects_student_select on storage.objects for select to authenticated using (bucket_id='resumes' and (storage.foldername(name))[1]=auth.uid()::text);
