create policy resumes_objects_student_update on storage.objects for update to authenticated using (bucket_id='resumes' and (storage.foldername(name))[1]=auth.uid()::text) with check (bucket_id='resumes' and (storage.foldername(name))[1]=auth.uid()::text);
create policy resumes_objects_student_delete on storage.objects for delete to authenticated using (bucket_id='resumes' and (storage.foldername(name))[1]=auth.uid()::text);
